from pathlib import Path
import json,statistics,hashlib
r=Path(__file__).parent
runs=[json.loads((r/f'final{i}/qkv_final.json').read_text()) for i in range(4)]
rows={}
for name in runs[0]['rounds'][1]['median_us']:
 vals=[d['rounds'][1]['median_us'][name] for d in runs]
 rows[name]=dict(median_us=statistics.median(vals),per_gpu_us=vals,min_us=min(vals),max_us=max(vals))
valid={p.stem:json.loads(p.read_text()) for p in (r/'validation').glob('stress-*.json')}
summary=dict(scope='C8 isolated group5 input quant through Q norm/RoPE; 1k/1k decode shape; not end-to-end',method='Median across four GPU-specific second-round medians. Each GPU alternates all variants in one sweep; flat HIP graphs with32 repetitions,5warmups,40samples per round; two rounds. No serving runs.',timings=rows,resources=runs[0]['validation']['resources'],validation={k:{a:b for a,b in v.items() if a!='checks'} for k,v in valid.items()},selected=dict(SPLITS=16,BN=128,LOCAL=True,PRE=True,SEM=False,ATOMIC=False),not_integrated=True)
(r/'RESULTS.json').write_text(json.dumps(summary,indent=2))
labels={'native':('ATOM native','—','—'),'old':('Previous fused group','16','128 / 192'),'local':('Local quant only','16','128 / 192'),'early':('Local quant + early prefetch (selected)','16','128 / 192'),'sem':('Above + QA-only readiness','16','128 / 192'),'s8n128':('All three changes','8','128 / 96'),'s8n64':('All three changes','8','64 / 192'),'s4n128':('All three changes','4','128 / 48'),'s4n32':('All three changes','4','32 / 192'),'atomic16':('All three + FP32 atomics','16','128 / 192'),'atomic8':('All three + FP32 atomics','8','64 / 192'),'atomic4':('All three + FP32 atomics','4','32 / 192')}
lines=['# C8 QKV dependency ablations — 2026-10-21','','Selected: local producer quantization + bounded pre-B2 QB L2 prefetch, split16 / output tile128. Retain B3: QA-only readiness did not provide a measured win. No serving/full-layer integration performed.','','Times are microseconds for the entire eight-row group: input quant, QA/KV projection, split reduction/norm/quant, QB, Q norm/RoPE. Current KV produced; production cache scatter is outside this fixture. No new group6/SWA timing.','','Reported value: median of four GPU-specific second-round medians, all variants interleaved on each GPU; first round discarded. This is microbenchmark timing, not a client result. See per-GPU data and samples in final0..3.','','|Variant|K splits|Output tile / projection CTAs|Time us|GPU range us|','|---|---:|---:|---:|---:|']
for n,d in rows.items():
 a,b,c=labels[n];lines.append(f"|{a}|{b}|{c}|{d['median_us']:.3f}|{d['min_us']:.3f}–{d['max_us']:.3f}|")
lines+=['','## Validation','','All variants were compiled and checked for zero spills before launch; selected uses '+str(summary['resources']['early'])+'. Compiled ISA/LLVM and metadata are retained. Non-speculative prefetch uses tensor descriptor bounds. Assembly confirms prefetch instructions before B2 atomic/poll, scaled WMMA, and device-scope buffer polling.','','Stress tests use32 seeds: zero input, random inputs, saved live activation plus perturbations, and row-varying scales. Each case runs two32-launch graph replays without resetting counters/epochs (2048 candidate invocations per variant). Check output poison overwrites, Q/KV/raw outputs, FP8 activations/scales, and health flags. Exact comparisons are to the previous fused path, not a claim of model-wide exactness. Worst relative RMS to native is reported below.']
for k,v in summary['validation'].items():lines.append(f"- {k}: {v['cases']} checks, Q exact vs previous={v['all_q_exact']}, FP8/scales exact={v['all_fp8_equal']}, Q native relative RMS max={v['max_q_native_rms']:.9g}, KV previous RMS max={v['max_kv_rms']:.9g}.")
lines+=['','## Findings and rejected trials','','- Local quant removes B1 and global FP8 input handoff. Each producer uses TDM BF16 input and locally converts/scales complete128-element groups before WMMA.','- Earlier prefetch provides a smaller improvement. It is issued after projection stores, before the B2 synchronization. Existing first-QB-tile early TDM is retained.','- QA-only readiness uses an8-arrival device counter plus256 per-CTA monotonic epoch slots; release producers/coherent load polling. It is correct on tested graphs but adds epoch bookkeeping, and is not selected.','- Split8/BN64 and split4/BN32 maintain192 projection CTAs. Split8 comes close; split4 loses despite preserving CTA count. Smaller split means more K work and quantization per CTA, while narrow N tiles provide less output reuse.','- Atomic initialization is included inside the fused launch before a barrier. No outside memset is hidden. Initial ordinary loads of the reused atomic scratch produced large errors on the initializing QA finisher CTAs. Device-coherent buffer loads fixed the tested errors; retain this fix. Initial invalid timings in gpu3 are diagnostic only; use atomic-fixed and final0..3 for valid atomic results.','- Atomics do not beat explicit reduction even at split8. They require initialization and contested updates; individual costs were not separately timed.','- No inference should be made that the regional speedup translates directly to full-model tokens/s. Full-layer residency and dual-forward validation remain required.','','## Reproduce / integration','','Use the existing vigokhal_dsv4_tp4 image environment, /home/vigokhal/dsv4-monokernel mounted as /work, model under /data. One worker per GPU; check ownership first. Run final_sweep.py with HIP_VISIBLE_DEVICES=0 and OUTDIR=/work/c8-qkv-deps/repeat0. Repeat on other GPUs in independent processes. Run stress.py --variant early (or sem/s8/s4/atomic). Existing common.py records the second round. Do not run build.py: it is the initial source-generation record, not a final build script.','','Selected qkv_candidate.qkv_batch defaults LOCAL=True, PRE=True, SPLITS=16, BN=128, SEM=False, ATOMIC=False. Selected path needs no Ready allocation; SEM=True requires Ready[257] int32 initialized once, then reused on sequential graph invocations. Original argument signature otherwise retained, with optional experimental constexpr parameters appended. Scratch P remains[16,M,1536]. Preserve all production BatchId/Dest/cache masks and early prefetch bounds. Compile the full monokernel and verify zero spills and one resident CTA per CU before launching; standalone resource numbers do not establish full-layer residency.','','The archive includes this experiment, Python dependencies, and the saved checkpoint-derived fixture. It still requires the matching ROCm/Triton/AITER/ATOM environment and model configuration.']
(r/'RESULTS.md').write_text('\n'.join(lines)+'\n')
files={str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for p in r.glob('*.py')}
(r/'SOURCE_SHA256.json').write_text(json.dumps(files,indent=2))
print(json.dumps({k:round(v['median_us'],3) for k,v in rows.items()}))
